-- بند الرسومات التنفيذية والتصاميم التكميلية (مسؤولية المقاول) + إدراجه في كل النطاقات
insert into public.ls_items (code, grp, title, descr, unit, sort) values
('LS-40', 'أعمال عامة وتحضيرية', 'الرسومات التنفيذية والتصاميم التكميلية', 'إعداد وتقديم الرسومات التنفيذية (Shop Drawings) لجميع الأعمال قبل التنفيذ، وإعداد التصاميم التكميلية حيث لا تكفي المخططات المرفقة أو تخلو من التفاصيل (مثل: تفاصيل التمديدات الكهربائية والإنارة ولوحات التوزيع، توزيع الأثاث، التكييف، التيار الخفيف، التفاصيل المعمارية)، بواسطة مهندسين مختصين وعلى حساب المقاول، واعتمادها من المهندس المشرف قبل البدء، مع تسليم مخططات كما نُفِّذ (As-built) في النهاية؛ ويُعدّ ذلك مشمولاً في السعر.', 'مقطوعية', 35)
on conflict (code) do nothing;
update public.ls_templates set codes = array_append(codes, 'LS-40'), updated_at = now() where not ('LS-40' = any(codes));
